<script setup lang="ts">import{computed,onMounted,ref}from'vue';import DefaultLayout from'@/layouts/DefaultLayout.vue';import{useAuthStore}from'@/stores/auth';import{useApi}from'@/composables/useApi';import type{ApiResponse,Enrollment}from'@/types';const auth=useAuthStore(),api=useApi(),items=ref<Enrollment[]>([]);const completed=computed(()=>items.value.filter(x=>x.status==='COMPLETED').length),average=computed(()=>items.value.length?Math.round(items.value.reduce((n,x)=>n+x.progressPercent,0)/items.value.length):0);onMounted(async()=>{const r=await api.get<ApiResponse<Enrollment[]>>('/enrollments/me');items.value=r.data||[]})</script>
<template><DefaultLayout><main class="mx-auto max-w-7xl px-4 py-10"><h1 class="text-3xl font-extrabold">Xin chào, {{auth.user?.fullName}}! 👋</h1><p class="mt-2 text-slate-500">Tiếp tục hành trình học tập của bạn.</p><div class="my-8 grid gap-5 sm:grid-cols-3"><div class="rounded-2xl border bg-white p-6 dark:border-slate-800 dark:bg-slate-900"><p class="text-3xl font-black text-purple-600">{{items.length}}</p><p>Khóa học đã đăng ký</p></div><div class="rounded-2xl border bg-white p-6 dark:border-slate-800 dark:bg-slate-900"><p class="text-3xl font-black text-emerald-600">{{completed}}</p><p>Khóa học hoàn thành</p></div><div class="rounded-2xl border bg-white p-6 dark:border-slate-800 dark:bg-slate-900"><p class="text-3xl font-black text-amber-500">{{average}}%</p><p>Tiến độ trung bình</p></div></div><div class="rounded-3xl bg-gradient-to-r from-indigo-600 to-purple-600 p-8 text-white"><h2 class="text-2xl font-bold">Sẵn sàng học tiếp?</h2><p class="mt-2 text-purple-100">Mở khóa học của bạn hoặc khám phá nội dung mới.</p><div class="mt-6 flex gap-3"><RouterLink to="/my-courses" class="rounded-xl bg-white px-5 py-3 font-bold text-purple-700">Khóa học của tôi</RouterLink><RouterLink to="/courses" class="rounded-xl border border-white/40 px-5 py-3 font-bold">Khám phá</RouterLink></div></div></main></DefaultLayout></template>
